#!/usr/bin/env node

import fs from "node:fs";
import path from "node:path";

const root = path.resolve("content/frontend-fresher/css-advanced-fresher");
const paragraph = (...parts) => parts.join("\n\n");
const code = (lines) => `\`\`\`${lines[0]}\n${lines.slice(1).join("\n")}\n\`\`\``;

function makeQuestion(topicSlug, index, spec) {
  const number = String(index + 1).padStart(3, "0");
  const suffixes = ["interview-basics", "when-to-use", "common-mistake", "compare"];
  return {
    id: `css-advanced-fresher-${topicSlug}-q${number}`,
    slug: `css-advanced-fresher-${topicSlug}-${suffixes[index]}`,
    question: spec.question,
    title: spec.title,
    direct_answer: spec.direct,
    layout_type: index === 0 ? "concept-explanation" : "interview-practice",
    difficulty: spec.difficulty ?? "easy",
    importance: index === 0 ? "high" : spec.importance ?? "medium",
    reading_time_minutes: spec.readingTime ?? 6,
    interviewer_intent: spec.intent,
    answer: {
      sections: [
        { type: "key_points", title: "Quick revision", items: spec.quick },
        {
          type: "speakable_answer",
          title: "Interview answer",
          answerSize: spec.answerSize ?? "compact",
          content: spec.speaking,
        },
        { type: "overview", title: spec.overviewTitle, content: spec.overview },
        { type: "deep_explanation", title: spec.deepTitle, content: spec.deep },
        { type: spec.visualType ?? "diagram", title: spec.visualTitle, content: spec.visual },
        { type: "code_example", title: spec.codeTitle, content: `${spec.code}\n${spec.codeNote}` },
      ],
    },
    followup_questions: spec.followups,
    order: index + 1,
    seo: {
      metaTitle: `${spec.title} — frontend interview question | InterviewExplainer`,
      metaDescription: spec.direct.length > 157 ? `${spec.direct.slice(0, 154)}...` : spec.direct,
    },
  };
}

